import fs from 'node:fs';
let cached=null,time=0,inflight=null;
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('Public launch data unavailable');return r.json();}
export async function collectLaunches(){const profiles=await json('https://api.dexscreener.com/token-profiles/latest/v1');const selected=(Array.isArray(profiles)?profiles:[]).filter(p=>p.chainId==='solana'&&/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(p.tokenAddress)&&p.tokenAddress.endsWith('pump')).slice(0,15);if(!selected.length)return {asOf:new Date().toISOString(),tokens:[],source:'DexScreener · pump.fun-origin addresses',snapshot:false};const pairs=await json('https://api.dexscreener.com/tokens/v1/solana/'+selected.map(p=>p.tokenAddress).join(','));const tokens=selected.flatMap(profile=>{const matches=(Array.isArray(pairs)?pairs:[]).filter(p=>p.chainId==='solana'&&p.baseToken?.address===profile.tokenAddress).sort((a,b)=>(b.liquidity?.usd||0)-(a.liquidity?.usd||0));const p=matches[0];if(!p)return [];return [{mint:profile.tokenAddress,name:p.baseToken.name,symbol:p.baseToken.symbol,image:profile.icon||p.info?.imageUrl||null,url:p.url,dex:p.dexId,price:Number(p.priceUsd)||null,marketCap:p.marketCap??p.fdv??null,liquidity:p.liquidity?.usd??null,volume:p.volume?.h24??null,buys:p.txns?.h24?.buys??0,sells:p.txns?.h24?.sells??0,createdAt:p.pairCreatedAt||null,description:profile.description||'',state:p.dexId==='pumpfun'?'Trading':'Market pool'}];});return {asOf:new Date().toISOString(),tokens,source:'DexScreener · pump.fun-origin addresses',snapshot:false};}
function fallback(){if(cached)return {...cached,snapshot:true};try{return {...JSON.parse(fs.readFileSync(new URL('../data/launches.json',import.meta.url),'utf8')),snapshot:true};}catch{return {asOf:null,tokens:[],snapshot:true,error:'Public launch data temporarily unavailable'};}}
export async function getLaunches(){if(cached&&Date.now()-time<60000)return cached;if(!inflight)inflight=collectLaunches().then(d=>{cached=d;time=Date.now();return d;}).catch(fallback).finally(()=>inflight=null);return inflight;}
export default async function handler(req,res){res.setHeader('content-type','application/json');if(req.method!=='GET'){res.statusCode=405;res.end(JSON.stringify({error:'Method not allowed'}));return;}res.setHeader('Cache-Control','s-maxage=60, stale-while-revalidate=60');res.end(JSON.stringify(await getLaunches()));}
